bugRepair.brokenCode:
.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  /* المشكلة: الحاوية الأب تفتقر إلى position: relative */
}

bugRepair.fixedCode:
.dropdown {
  position: relative;
}
.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
}

bugRepair.brokenCode:
.icon-home {
  width: 24px;
  height: 24px;
  background-image: url('sprites.png');
  /* النتيجة: تظهر أجزاء من الأيقونات المجاورة داخل الصندوق */
}

bugRepair.fixedCode:
.icon-home {
  width: 24px;
  height: 24px;
  background-image: url('sprites.png');
  background-repeat: no-repeat;
  background-position: 0 0;
}

